-- Futures Trade Correction Message
tmx_mx_solamulticast_hsvf_v1_12_2.futures_trade_correction_message = {}

-- Calculate size of: Futures Trade Correction Message
tmx_mx_solamulticast_hsvf_v1_12_2.futures_trade_correction_message.size = function(buffer, offset)
  local index = 0

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.long_message_header.size

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.exchange_id.size

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.future_product.size

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.volume.size

  -- Calculate runtime size of Trade Price Fraction Pair field
  local trade_price_fraction_pair_offset = offset + index
  local trade_price_fraction_pair_type = buffer(trade_price_fraction_pair_offset + 7, 1):string()
  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.trade_price_fraction_pair.size(buffer, trade_price_fraction_pair_offset, trade_price_fraction_pair_type)

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.net_change_sign.size

  -- Calculate runtime size of Net Change Fraction Pair field
  local net_change_fraction_pair_offset = offset + index
  local net_change_fraction_pair_type = buffer(net_change_fraction_pair_offset + 7, 1):string()
