-- Calculate size of: Option Symbol
tmx_mx_solamulticast_hsvf_v1_12_2.option_symbol.size = function(buffer, offset)
  local index = 0

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.root_symbol.size

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.expiry_month.size

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.filler_1.size

  -- Calculate runtime size of Strike Price Fraction Pair field
  local strike_price_fraction_pair_offset = offset + index
  local strike_price_fraction_pair_type = buffer(strike_price_fraction_pair_offset + 7, 1):string()
  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.strike_price_fraction_pair.size(buffer, strike_price_fraction_pair_offset, strike_price_fraction_pair_type)

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.expiry_year.size

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.expiry_day.size

