-- Strategy Instrument Keys Message
tmx_mx_solamulticast_hsvf_v1_12_2.strategy_instrument_keys_message = {}

-- Calculate size of: Strategy Instrument Keys Message
tmx_mx_solamulticast_hsvf_v1_12_2.strategy_instrument_keys_message.size = function(buffer, offset)
  local index = 0

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.long_message_header.size

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.exchange_id.size

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.strategy_symbol.size

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.expiry_year.size

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.expiry_month_strategy.size

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.expiry_day.size

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.maximum_number_of_contracts_per_order.size

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.minimum_number_of_contracts_per_order.size

  -- Calculate runtime size of Maximum Threshold Price Fraction Pair field
  local maximum_threshold_price_fraction_pair_offset = offset + index
  local maximum_threshold_price_fraction_pair_type = buffer(maximum_threshold_price_fraction_pair_offset + 7, 1):string()
  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.maximum_threshold_price_fraction_pair.size(buffer, maximum_threshold_price_fraction_pair_offset, maximum_threshold_price_fraction_pair_type)

  -- Calculate runtime size of Minimum Threshold Price Fraction Pair field
  local minimum_threshold_price_fraction_pair_offset = offset + index
  local minimum_threshold_price_fraction_pair_type = buffer(minimum_threshold_price_fraction_pair_offset + 7, 1):string()
  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.minimum_threshold_price_fraction_pair.size(buffer, minimum_threshold_price_fraction_pair_offset, minimum_threshold_price_fraction_pair_type)

  -- Calculate runtime size of Tick Increment field
  local tick_increment_offset = offset + index
  local tick_increment_type = buffer(tick_increment_offset + 7, 1):string()
  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.tick_increment.size(buffer, tick_increment_offset, tick_increment_type)

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.market_flow_indicator.size

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.group_instrument.size

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.instrument.size

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.instrument_external_code.size

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.strategy_allow_implied.size

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.strategy_code.size

  index = index + tmx_mx_solamulticast_hsvf_v1_12_2.number_of_legs.size

  -- Calculate field size from count
  local strategy_instrument_leg_count = buffer(offset + index - 2, 2):string()
  index = index + strategy_instrument_leg_count * 35

  return index
end

-- Display: Strategy Instrument Keys Message
tmx_mx_solamulticast_hsvf_v1_12_2.strategy_instrument_keys_message.display = function(packet, parent, length)
  return ""
end

-- Dissect Fields: Strategy Instrument Keys Message
tmx_mx_solamulticast_hsvf_v1_12_2.strategy_instrument_keys_message.fields = function(buffer, offset, packet, parent)
  local index = offset

  -- Long Message Header: Struct of 1 fields
  index, long_message_header = tmx_mx_solamulticast_hsvf_v1_12_2.long_message_header.dissect(buffer, index, packet, parent)

  -- Exchange Id: A
  index, exchange_id = tmx_mx_solamulticast_hsvf_v1_12_2.exchange_id.dissect(buffer, index, packet, parent)

  -- Strategy Symbol: X
  index, strategy_symbol = tmx_mx_solamulticast_hsvf_v1_12_2.strategy_symbol.dissect(buffer, index, packet, parent)

  -- Expiry Year: N
  index, expiry_year = tmx_mx_solamulticast_hsvf_v1_12_2.expiry_year.dissect(buffer, index, packet, parent)

  -- Expiry Month Strategy: A
  index, expiry_month_strategy = tmx_mx_solamulticast_hsvf_v1_12_2.expiry_month_strategy.dissect(buffer, index, packet, parent)

  -- Expiry Day: N
  index, expiry_day = tmx_mx_solamulticast_hsvf_v1_12_2.expiry_day.dissect(buffer, index, packet, parent)

  -- Maximum Number Of Contracts Per Order: X
  index, maximum_number_of_contracts_per_order = tmx_mx_solamulticast_hsvf_v1_12_2.maximum_number_of_contracts_per_order.dissect(buffer, index, packet, parent)

  -- Minimum Number Of Contracts Per Order: X
  index, minimum_number_of_contracts_per_order = tmx_mx_solamulticast_hsvf_v1_12_2.minimum_number_of_contracts_per_order.dissect(buffer, index, packet, parent)

  -- Dependency element: Maximum Threshold Price Fraction Indicator
  local maximum_threshold_price_fraction_indicator = buffer(index + 7, 1):string()

  -- Maximum Threshold Price Fraction Pair: Runtime Type with 8 branches
  index = tmx_mx_solamulticast_hsvf_v1_12_2.maximum_threshold_price_fraction_pair.dissect(buffer, index, packet, parent, maximum_threshold_price_fraction_indicator)

  -- Dependency element: Minimum Threshold Price Fraction Indicator
  local minimum_threshold_price_fraction_indicator = buffer(index + 7, 1):string()

  -- Minimum Threshold Price Fraction Pair: Runtime Type with 8 branches
  index = tmx_mx_solamulticast_hsvf_v1_12_2.minimum_threshold_price_fraction_pair.dissect(buffer, index, packet, parent, minimum_threshold_price_fraction_indicator)

  -- Dependency element: Tick Increment Fraction Indicator
  local tick_increment_fraction_indicator = buffer(index + 7, 1):string()

  -- Tick Increment: Runtime Type with 9 branches
  index = tmx_mx_solamulticast_hsvf_v1_12_2.tick_increment.dissect(buffer, index, packet, parent, tick_increment_fraction_indicator)

  -- Market Flow Indicator: X
  index, market_flow_indicator = tmx_mx_solamulticast_hsvf_v1_12_2.market_flow_indicator.dissect(buffer, index, packet, parent)

  -- Group Instrument: X
  index, group_instrument = tmx_mx_solamulticast_hsvf_v1_12_2.group_instrument.dissect(buffer, index, packet, parent)

  -- Instrument: X
  index, instrument = tmx_mx_solamulticast_hsvf_v1_12_2.instrument.dissect(buffer, index, packet, parent)

  -- Instrument External Code: X
  index, instrument_external_code = tmx_mx_solamulticast_hsvf_v1_12_2.instrument_external_code.dissect(buffer, index, packet, parent)

  -- Strategy Allow Implied: A
  index, strategy_allow_implied = tmx_mx_solamulticast_hsvf_v1_12_2.strategy_allow_implied.dissect(buffer, index, packet, parent)

  -- Strategy Code: X
  index, strategy_code = tmx_mx_solamulticast_hsvf_v1_12_2.strategy_code.dissect(buffer, index, packet, parent)

  -- Number Of Legs: N
  index, number_of_legs = tmx_mx_solamulticast_hsvf_v1_12_2.number_of_legs.dissect(buffer, index, packet, parent)

  -- Repeating: Strategy Instrument Leg
  for strategy_instrument_leg_index = 1, number_of_legs do
    index, strategy_instrument_leg = tmx_mx_solamulticast_hsvf_v1_12_2.strategy_instrument_leg.dissect(buffer, index, packet, parent, strategy_instrument_leg_index)
  end

  return index
end

