tmx_mx_solamulticast_hsvf_v1_12_2.packet.dissect = function(buffer, packet, parent)
  local index = 0

  -- Dependency for Packet
  local end_of_payload = buffer:len()

  while index < end_of_payload do

    -- Hsvf Stx: character
    index, hsvf_stx = tmx_mx_solamulticast_hsvf_v1_12_2.hsvf_stx.dissect(buffer, index, packet, parent)

    -- Message Header: Struct of 2 fields
