  packet.cols.protocol = omi_tmx_mx_solamulticast_hsvf_v1_12_2.name

  -- Dissect protocol
  local protocol = parent:add(omi_tmx_mx_solamulticast_hsvf_v1_12_2, buffer(), omi_tmx_mx_solamulticast_hsvf_v1_12_2.description, "("..buffer:len().." Bytes)")
  return tmx_mx_solamulticast_hsvf_v1_12_2.packet.dissect(buffer, packet, protocol)
end


