-----------------------------------------------------------------------

-- Verify Hsvf Stx Field
tmx_mx_solamulticast_hsvf_v1_12_2.hsvf_stx.verify = function(buffer)
  -- Too short to carry the field: not this protocol
  if buffer:len() < 0 + 1 then
    return false
  end

  -- Attempt to read field
  local value = buffer(0, 1):int()

  if value == 2 then
    return true
  end

  return false
end

-- Dissector Heuristic for Tmx Mx SolaMulticast Hsvf 1.12.2 (Udp)
local function omi_tmx_mx_solamulticast_hsvf_v1_12_2_udp_heuristic(buffer, packet, parent)
  -- Verify packet length
  if not tmx_mx_solamulticast_hsvf_v1_12_2.packet.requiredsize(buffer) then return false end

  -- Verify Hsvf Stx
  if not tmx_mx_solamulticast_hsvf_v1_12_2.hsvf_stx.verify(buffer) then return false end

  -- Protocol is valid, set conversation and dissect this packet
  packet.conversation = omi_tmx_mx_solamulticast_hsvf_v1_12_2
  omi_tmx_mx_solamulticast_hsvf_v1_12_2.dissector(buffer, packet, parent)

  return true
end

